<script lang="ts">
 import QRCode from 'qrcode'; let url='';let svg='';let mode='qr';let shortUrl='';let error='';let working=false;
 async function qr(v:string){url=v;if(v&&mode==='qr')svg=await QRCode.toString(v,{type:'svg',margin:2});else svg=''}
 async function shorten(){working=true;try{let r=await fetch('/api/shorten',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});let d=await r.json();if(!r.ok)throw Error(d.error);shortUrl=d.shortUrl}catch(e){error=e instanceof Error?e.message:'Ralat'}finally{working=false}}
 async function download(format:'png'|'svg'){if(!url.trim()||!svg)return;const content=format==='svg'?svg:await QRCode.toDataURL(url.trim(),{width:1600,margin:2});const href=format==='svg'?URL.createObjectURL(new Blob([content],{type:'image/svg+xml'})):content;const link=document.createElement('a');link.href=href;link.download=`qora-qr.${format}`;link.click();if(format==='svg')URL.revokeObjectURL(href)}
</script>
<main><header><a href="/">qora</a><nav><button>about</button><button>settings</button></nav></header><section><h1>{mode==='qr'?'QR untuk pautan anda.':'Pendekkan pautan anda.'}</h1><p>{mode==='qr'?'tampal satu pautan, kemudian muat turun QR.':'buat pautan pendek tanpa ubah QR asal anda.'}</p><div class="entry"><span>⌁</span><input value={url} on:input={e=>qr(e.currentTarget.value)} placeholder="paste the link here"/>{#if mode==='shorten'}<button class="go" on:click={shorten}>{working?'…':'→'}</button>{/if}</div><div class="tools"><div><button on:click={()=>{mode='qr';qr(url)}} class:active={mode==='qr'}>✦ QR</button><button on:click={()=>{mode='shorten';svg=''}} class:active={mode==='shorten'}>↗ short</button></div><button class="paste" on:click={()=>navigator.clipboard.readText().then(qr)}>paste</button></div>{#if svg}<div class="qr">{@html svg}<div><button on:click={()=>download('png')}>PNG</button><button on:click={()=>download('svg')}>SVG</button></div></div>{/if}{#if shortUrl}<code>{shortUrl}</code>{/if}{#if error}<em>{error}</em>{/if}<small class="notice">QR terus ke pautan asal · short link ialah servis berasingan</small></section></main>
<style>main{min-height:100dvh;background:#fff;color:#171717}header{height:50px;display:flex;align-items:center;justify-content:space-between;width:min(1040px,92%);margin:auto;font:600 13px ui-monospace,SFMono-Regular,monospace}header a{color:#171717;text-decoration:none;font-weight:800}header nav{display:flex;gap:14px}header button{border:0;background:transparent;color:#888;font:inherit}section{width:min(610px,88%);min-height:calc(100dvh - 50px);margin:auto;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:34px 0;text-align:center}.mark{position:relative;width:92px;height:92px;margin-bottom:22px;border:2px solid #171717;border-radius:50%}.mark:before,.mark:after{content:'';position:absolute;inset:20px;border:2px solid #171717;border-radius:50%}.mark:after{inset:35px;background:#171717}.mark i{position:absolute;width:16px;height:16px;background:#fff;border:2px solid #171717}.mark i:nth-child(1){top:-4px;left:38px}.mark i:nth-child(2){right:-4px;top:38px}.mark i:nth-child(3){bottom:-4px;left:38px}.mark i:nth-child(4){left:-4px;top:38px}h1{margin:0;font:700 clamp(2rem,5vw,3.2rem)/1 ui-monospace,SFMono-Regular,monospace;letter-spacing:-.08em}p{margin:14px 0 28px;color:#777;font:14px/1.5 ui-monospace,SFMono-Regular,monospace}.entry{display:flex;align-items:center;width:100%;height:52px;border:1px solid #222;border-radius:12px;padding:0 14px;box-shadow:0 2px 0 #eee}.entry span{color:#999;font-size:20px}.entry input{flex:1;min-width:0;height:100%;border:0;outline:0;padding:0 12px;background:transparent;font:14px ui-monospace,SFMono-Regular,monospace}.go{border:0;background:#171717;color:#fff;border-radius:8px;width:32px;height:32px;font-size:18px}.tools{display:flex;justify-content:space-between;width:100%;margin-top:7px}.tools div{display:flex;border:1px solid #ddd;border-radius:10px;overflow:hidden}.tools button{border:0;border-right:1px solid #ddd;padding:9px 12px;background:#fff;color:#666;font:600 13px ui-monospace,SFMono-Regular,monospace}.tools button:last-child{border:0}.tools .active{background:#171717;color:#fff}.tools .paste{border:1px solid #ddd;border-radius:10px}.qr{width:220px;margin-top:30px;padding:14px;border:1px solid #ddd;border-radius:14px}.qr :global(svg){width:100%;height:100%}.qr div{display:flex;gap:6px;justify-content:center;margin-top:8px}.qr button{border:1px solid #ddd;border-radius:7px;background:#fff;padding:6px 9px;font:600 11px ui-monospace,SFMono-Regular,monospace}code{max-width:100%;margin-top:28px;padding:12px;border:1px solid #ddd;border-radius:10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}em{margin-top:16px;color:#b22;font:13px ui-monospace,SFMono-Regular,monospace}.notice{margin-top:22px;color:#aaa;font:11px ui-monospace,SFMono-Regular,monospace}@media(max-width:600px){section{justify-content:flex-start;padding-top:70px}.mark{width:76px;height:76px}.mark:before{inset:16px}.mark:after{inset:29px}.mark i:nth-child(1),.mark i:nth-child(3){left:30px}.mark i:nth-child(2),.mark i:nth-child(4){top:30px}h1{font-size:2rem}.qr{width:190px}}</style>
